/// Categories shown in the rider's timeline.
enum RiderLogType {
  /// A lesson with an instructor.
  lesson('Lesson'),

  /// Independent practice or a training ride.
  training('Training ride'),

  /// A competition or show.
  show('Show'),

  /// A care event or veterinary appointment.
  care('Care / vet'),

  /// A personal journal entry.
  reflection('Reflection'),

  /// A record generated by the app.
  activity('Activity');

  const RiderLogType(this.label);

  /// Display name in the timeline and filter.
  final String label;
}

/// Optional structured fields on a rider note. Legacy notes omit this map.
class RiderLogDetails {
  /// Creates the structured portion of a rider entry.
  const RiderLogDetails({
    required this.type,
    this.title,
    this.instructor,
    this.horse,
    this.horseId,
    this.placing,
    this.authorRole,
    this.shared = false,
    this.focus,
    this.nextSteps,
  });

  /// Category of the journal entry.
  final RiderLogType type;

  /// Optional headline.
  final String? title;

  /// Instructor recorded for the lesson.
  final String? instructor;

  /// Optional name of the horse involved.
  final String? horse;

  /// Profile ID when the rider selects a linked horse.
  final String? horseId;

  /// Optional result text for a show.
  final String? placing;

  /// The role recorded for an entry submitted by a coach.
  final String? authorRole;

  /// Whether this note is stored as a shared journal record.
  final bool shared;

  /// Work or skills the rider focused on.
  final String? focus;

  /// What the rider plans to do next.
  final String? nextSteps;

  /// Reads structured fields when the map has a supported category.
  static RiderLogDetails? fromMap(Object? value) {
    if (value is! Map) return null;
    final type = RiderLogType.values.asNameMap()[value['type']];
    if (type == null) return null;

    String? text(String key) {
      final field = value[key];
      return field is String && field.trim().isNotEmpty ? field : null;
    }

    return RiderLogDetails(
      type: type,
      title: text('title'),
      instructor: text('instructor'),
      horse: text('horse'),
      horseId: text('horseId'),
      placing: text('placing'),
      authorRole: text('authorRole'),
      shared: value['shared'] == true,
      focus: text('focus'),
      nextSteps: text('nextSteps'),
    );
  }

  /// Serializes the structured fields for Firestore.
  Map<String, Object?> toMap() => {
    'type': type.name,
    if (title != null) 'title': title,
    if (instructor != null) 'instructor': instructor,
    if (horse != null) 'horse': horse,
    if (horseId != null) 'horseId': horseId,
    if (placing != null) 'placing': placing,
    if (authorRole != null) 'authorRole': authorRole,
    if (shared) 'shared': true,
    if (focus != null) 'focus': focus,
    if (nextSteps != null) 'nextSteps': nextSteps,
  };
}
